import java.io.BufferedReader
import java.io.InputStreamReader
import java.io.BufferedWriter
import java.io.OutputStreamWriter

const val MOD = 1000000007L

fun multiply(one: Array<IntArray>, two: Array<IntArray>, m: Int): Array<IntArray> {
    val res = Array(m) { IntArray(m) }
    for (i in 0 until m) {
        for (j in 0 until m) {
            var sum = 0L
            for (k in 0 until m) {
                sum += (one[i][k].toLong() * two[k][j]) % MOD
            }
            res[i][j] = (sum % MOD).toInt()
        }
    }
    return res
}

fun power(exp: Long, base: Array<IntArray>, m: Int): Array<IntArray> {
    if (exp == 1L) {
        return base
    }
    val res = power(exp / 2, base, m)
    val squared = multiply(res, res, m)
    return if (exp and 1L == 1L) {
        multiply(squared, base, m)
    } else {
        squared
    }
}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val bw = BufferedWriter(OutputStreamWriter(System.out))

    val input = br.readLine()!!.split(" ").map { it.toLong() }
    val n = input[0]
    val m = input[1].toInt()

    if (n < m) {
        bw.write("1")
        bw.flush()
        return
    }
    if (n == m) {
        bw.write("2")
        bw.flush()
        return
    }

    val matrix = Array(m) { IntArray(m) }
    matrix[0][0] = 1
    matrix[0][m - 1] = 1
    for (i in 1 until m) {
        matrix[i][i - 1] = 1
    }

    val result = power(n, matrix, m)
    bw.write(result[0][0].toString())
    bw.flush()
}

