import java.io.InputStreamReader
import java.io.PrintWriter

const val MOD = 1000000007

fun multiply(a: Array<IntArray>, b: Array<IntArray>): Array<IntArray> {
    val m = a.size
    val res = Array(m) { IntArray(m) }
    for (i in 0 until m) {
        for (j in 0 until m) {
            var sum = 0L
            for (k in 0 until m) {
                sum += (a[i][k].toLong() * b[k][j]) % MOD
            }
            res[i][j] = (sum % MOD).toInt()
        }
    }
    return res
}

fun power(exp: Long, base: Array<IntArray>): Array<IntArray> {
    val m = base.size
    var result = Array(m) { IntArray(m) }.also { 
        for (i in 0 until m) it[i][i] = 1 
    }
    var currentBase = base
    var e = exp
    while (e > 0) {
        if (e and 1L == 1L) {
            result = multiply(result, currentBase)
        }
        currentBase = multiply(currentBase, currentBase)
        e = e shr 1
    }
    return result
}

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val writer = PrintWriter(System.out)

    val input = reader.readLine()!!.split(" ").map { it.toLong() }
    val n = input[0]
    val m = input[1].toInt()

    if (n < m) {
        writer.println(1)
        writer.flush()
        return
    }
    if (n == m) {
        writer.println(2)
        writer.flush()
        return
    }

    val matrix = Array(m) { IntArray(m) }
    matrix[0][0] = 1
    matrix[0][m - 1] = 1
    for (i in 1 until m) {
        matrix[i][i - 1] = 1
    }

    val resMatrix = power(n, matrix)
    writer.println(resMatrix[0][0])
    writer.flush()
}

